(()=>{'use strict';document.body.classList.add('js');
const menu=document.querySelector('.menu-button'),nav=document.querySelector('.nav');
function setMenu(open){nav.classList.toggle('is-open',open);menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Fechar':'Menu'}
menu.addEventListener('click',()=>setMenu(menu.getAttribute('aria-expanded')!=='true'));nav.addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){setMenu(false);menu.focus()}});matchMedia('(min-width:801px)').addEventListener('change',e=>{if(e.matches)setMenu(false)});
const reduce=matchMedia('(prefers-reduced-motion:reduce)'),wide=matchMedia('(min-width:801px) and (hover:hover) and (pointer:fine)'),intro=document.querySelector('[data-brand-intro]'),arrival=document.querySelector('[data-arrival]');let timer=0,frame=0,visible=true,destroyed=false;
function closeIntro(){clearTimeout(timer);timer=0;intro.hidden=true;document.body.classList.add('intro-complete')}
function playIntro(){if(reduce.matches||document.hidden){closeIntro();return}clearTimeout(timer);intro.hidden=false;document.body.classList.remove('intro-complete');timer=setTimeout(closeIntro,2350)}
document.querySelector('[data-skip-intro]').addEventListener('click',closeIntro);document.querySelector('[data-replay-intro]').addEventListener('click',playIntro);
document.addEventListener('keydown',()=>{if(!intro.hidden)closeIntro()});document.addEventListener('focusin',e=>{if(!intro.hidden&&!intro.contains(e.target))closeIntro()});document.addEventListener('pointerdown',e=>{if(!intro.hidden&&!intro.contains(e.target))closeIntro()},{passive:true});addEventListener('scroll',()=>{if(scrollY>80&&!intro.hidden)closeIntro()},{passive:true});
function paint(){frame=0;if(destroyed||document.hidden||!visible||!wide.matches||reduce.matches)return;const r=arrival.getBoundingClientRect(),range=Math.max(1,arrival.offsetHeight-arrival.querySelector('.arrival-stage').offsetHeight),p=Math.min(1,Math.max(0,-r.top/range));arrival.style.setProperty('--journey-scale',(1+p*.065).toFixed(4));arrival.style.setProperty('--journey-shift',(-p*15).toFixed(2)+'px');arrival.style.setProperty('--letter-shift',(-p*32).toFixed(2)+'px');arrival.dataset.journey=p.toFixed(3)}
function schedule(){if(!frame&&!destroyed&&visible&&wide.matches&&!reduce.matches&&!document.hidden)frame=requestAnimationFrame(paint)}
function preference(){cancelAnimationFrame(frame);frame=0;document.body.classList.toggle('entry-motion',wide.matches&&!reduce.matches);if(reduce.matches||!wide.matches){arrival.style.removeProperty('--journey-scale');arrival.style.removeProperty('--journey-shift');arrival.style.removeProperty('--letter-shift');delete arrival.dataset.journey}if(reduce.matches)closeIntro();schedule()}
addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});reduce.addEventListener('change',preference);wide.addEventListener('change',preference);document.addEventListener('visibilitychange',()=>{if(document.hidden){closeIntro();cancelAnimationFrame(frame);frame=0}else schedule()});addEventListener('pagehide',()=>{closeIntro();cancelAnimationFrame(frame);frame=0;destroyed=true});addEventListener('pageshow',e=>{if(e.persisted){destroyed=false;preference();schedule()}});
if('IntersectionObserver'in window){const sceneObserver=new IntersectionObserver(([x])=>{visible=x.isIntersecting;if(visible)schedule();else{cancelAnimationFrame(frame);frame=0}});sceneObserver.observe(arrival);const revealObserver=new IntersectionObserver(entries=>{for(const x of entries)if(x.isIntersecting){if(!reduce.matches)x.target.classList.add('reveal-running');revealObserver.unobserve(x.target)}},{threshold:.1});document.querySelectorAll('[data-reveal]').forEach(el=>revealObserver.observe(el))}
preference();if(!location.hash&&scrollY<80)playIntro();else closeIntro();
})();
